import { Edit2 } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Form, FormDrawer, Textarea } from '@/components/ui/form';

import {
  useUpdateComment,
  updateCommentInputSchema,
} from '../api/update-comment';

type EditCommentProps = {
  commentId: string;
  discussionId: string;
  initialBody: string;
};

export const EditComment = ({
  commentId,
  discussionId,
  initialBody,
}: EditCommentProps) => {
  const updateCommentMutation = useUpdateComment({
    discussionId,
  });

  return (
    <FormDrawer
      isDone={updateCommentMutation.isSuccess}
      triggerButton={
        <Button variant="ghost" size="sm" icon={<Edit2 className="size-4" />}>
          Edit Comment
        </Button>
      }
      title="Edit Comment"
      submitButton={
        <Button
          isLoading={updateCommentMutation.isPending}
          form="edit-comment"
          type="submit"
          size="sm"
          disabled={updateCommentMutation.isPending}
        >
          Submit
        </Button>
      }
    >
      <Form
        id="edit-comment"
        onSubmit={(values) => {
          updateCommentMutation.mutate({
            commentId,
            data: values,
          });
        }}
        schema={updateCommentInputSchema}
        options={{
          defaultValues: {
            body: initialBody,
          },
        }}
      >
        {({ register, formState }) => (
          <Textarea
            label="Body"
            error={formState.errors['body']}
            registration={register('body')}
          />
        )}
      </Form>
    </FormDrawer>
  );
};
